def transform(grid):
    h, w = len(grid), len(grid[0])
    # Each 3x3 cell records the most common color other than the background.
    # The background is the color occurring most often in the full input.
    from collections import Counter
    background = Counter(v for row in grid for v in row).most_common(1)[0][0]
    out = []
    for r in range(0, h, 3):
        row_out = []
        for c in range(0, w, 3):
            counts = Counter(
                grid[y][x]
                for y in range(r, min(r + 3, h))
                for x in range(c, min(c + 3, w))
                if grid[y][x] != background
            )
            row_out.append(counts.most_common(1)[0][0] if counts else 0)
        out.append(row_out)
    return out
