def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [[0] * (w // 3) for _ in range(h // 3)]
    for br in range(h // 3):
        for bc in range(w // 3):
            tile = [grid[r][bc*3:bc*3+3] for r in range(br*3, br*3+3)]
            counts = {}
            for row in tile:
                for v in row:
                    counts[v] = counts.get(v, 0) + 1
            # Retain a tile's color only when it is a solid 3x3 object;
            # zero is the output background.
            if len(counts) == 1 and next(iter(counts)) != 0:
                out[br][bc] = next(iter(counts))
    return out
